// Hidden affection score: insult -2, apology +1, gift +1; warm if score > 0.
function visible(actions) {
  let score = 0;
  for (const action of actions) {
    if (action === "insult") score -= 2;
    else if (action === "apologise") score += 1;
    else if (action === "gift") score += 1;
  }
  return { mood: score > 0 ? "warm" : "cold" };
}

// Hidden resentment: insult adds 2, apology removes 2, gift removes 1, clamped at 0; warm at 0.
function visible(actions) {
  let resentment = 0;
  for (const action of actions) {
    if (action === "insult") resentment += 2;
    else if (action === "apologise") resentment = Math.max(0, resentment - 2);
    else if (action === "gift") resentment = Math.max(0, resentment - 1);
  }
  return { mood: resentment === 0 ? "warm" : "cold" };
}

